// Bins in inncrements of one. 
std::vector<vector<int>> make_small_bins(int bin_pt_min, int bin_pt_max) {

    vector<vector<int>> bins;
    for (int i = 0; i < bin_pt_max - bin_pt_min; i++) {
        vector<int> bin = {bin_pt_min + i, bin_pt_min + i + 1, 1000};
        bins.push_back(bin);
    }
    return bins;
}

std::vector<vector<int>> final_bins(double bin_pt_min, double bin_pt_max) {
    
    vector<vector<int>> small_bins = make_small_bins(0,250);

    for (int iBin = 0; iBin < multipliers.size(); iBin++) {
        
        if (iBin < bin_pt_min) continue;

        double numEvents = small_bins[iBin][2] * multipliers[iBin];
        events_v_hat->AddPoint(iBin, numEvents);
    }
    
}

